values ('c0000000-0000-4000-8000-000000000003', $t$Reliance BP Mobility Limited · Promoted from Truck Stop Manager$t$, $t$Network Development Manager$t$, $t$India$t$, '2017-01-01', '2023-12-31', false, $t$2017 – 2023$t$, $t$2017 – 2023 · India · 6 Years$t$, $t$Reliance BP Mobility Limited · India$t$, $t$6-year tenure · State-wide network · 25+ direct reports. Promoted from Truck Stop Manager on commercial delivery. Sustained 15–20% annual sales growth for six consecutive years across two full business cycles.$t$, $t$State-wide petroleum dealer network · 25+ direct reports · B2B Fleet Card Programme · OPEX & commercial budget$t$, null, $j$[{"title":"Revenue & Commercial","points":[{"text":"15–20% annual sales growth for six consecutive years — directed multi-year strategic plans, dealer incentive frameworks, and promotional programmes that consistently beat commercial targets by 10–15%.","segments":[{"text":"15–20% annual sales growth for six consecutive years","strong":true},{"text":"— directed multi-year strategic plans, dealer incentive frameworks, and promotional programmes that consistently beat commercial targets by 10–15%.","strong":false}]},{"text":"Fleet Management Card Programme — drove and sustained approximately 15% growth in fleet-channel network sales through structured dealer engagement, performance tracking, and channel discipline.","segments":[{"text":"Fleet Management Card Programme","strong":true},{"text":"— drove and sustained approximately 15% growth in fleet-channel network sales through structured dealer engagement, performance tracking, and channel discipline.","strong":false}]}]},{"title":"Efficiency & Compliance","points":[{"text":"Implemented OMS across 30+ retail outlets — standardised order management, improved supply visibility, and strengthened execution consistency across the dealer network.","segments":[{"text":"Implemented OMS across 30+ retail outlets","strong":true},{"text":"— standardised order management, improved supply visibility, and strengthened execution consistency across the dealer network.","strong":false}]},{"text":"100% regulatory, safety, and environmental compliance maintained throughout a multi-year transformation.","segments":[{"text":"100% regulatory, safety, and environmental compliance","strong":true},{"text":"maintained throughout a multi-year transformation.","strong":false}]}]},{"title":"Expansion & Scale","points":[{"text":"8 new dealers onboarded — each committing ~USD 1.2M in station investment; partner evaluation and governance frameworks converted prospect conversations into long-term committed capital.","segments":[{"text":"8 new dealers onboarded","strong":true},{"text":"— each committing ~USD 1.2M in station investment; partner evaluation and governance frameworks converted prospect conversations into long-term committed capital.","strong":false}]},{"text":"25+ person cross-functional team led across channel development, dealer incentives, and partner management.","segments":[{"text":"25+ person cross-functional team","strong":true},{"text":"led across channel development, dealer incentives, and partner management.","strong":false}]}]},{"title":"Operations & Network Control","points":[{"text":"Owned operational performance across 30+ retail stations (COCO and DODO) spanning 10 districts in Tamil Nadu — ensuring network-level discipline across distributed assets.","segments":[{"text":"Owned operational performance across 30+ retail stations","strong":true},{"text":"(COCO and DODO) spanning 10 districts in Tamil Nadu — ensuring network-level discipline across distributed assets.","strong":false}]},{"text":"Product loss held materially below industry benchmarks — protecting channel partner economics through strengthened inventory governance and loss control systems.","segments":[{"text":"Product loss held materially below industry benchmarks","strong":true},{"text":"— protecting channel partner economics through strengthened inventory governance and loss control systems.","strong":false}]},{"text":"Stepped in as state-level SPOC for approximately 10 months — supporting senior leadership on network performance, issue resolution, and operational continuity.","segments":[{"text":"Stepped in as","strong":false},{"text":"state-level SPOC for approximately 10 months","strong":true},{"text":"— supporting senior leadership on network performance, issue resolution, and operational continuity.","strong":false}]}]}]$j$::jsonb, true, $t$p-rbp$t$, 3)
