values ('a2000000-0000-4000-8000-000000000005', null, $t$Built the B2B Fleet Card Programme from zero — 30% network sales growth in 6 months$t$, null, $t$+30% Sales$t$, $t$Owned full end-to-end go-to-market: framework design, portal build, station network integration, and rollout. No inherited structure. Delivered from framework design through network rollout.$t$, $j$[{"text":"Owned full end-to-end go-to-market: framework design, portal build, station network integration, and rollout. No inherited structure.","strong":false},{"text":"Delivered from framework design through network rollout.","strong":true}]$j$::jsonb, 5, 'impact', true)
