values ('a2000000-0000-4000-8000-000000000006', null, $t$15–20% annual sales growth across six consecutive years at Reliance BP$t$, null, $t$6 Yr Growth$t$, $t$Directed a state-wide dealer and distribution network through volatility and regulatory change. Beat commercial targets by 10–15% consistently through structured incentive frameworks and multi-year strategy.$t$, $j$[{"text":"Directed a state-wide dealer and distribution network through volatility and regulatory change.","strong":false},{"text":"Beat commercial targets by 10–15% consistently","strong":true},{"text":"through structured incentive frameworks and multi-year strategy.","strong":false}]$j$::jsonb, 6, 'impact', true)
