values ('a2000000-0000-4000-8000-000000000007', null, $t$Built an e-commerce delivery channel from zero — 500 million litres annual volume within 24 months$t$, null, $t$500M Litres$t$, $t$Established a new digital revenue channel and end-to-end operational model from the ground up. Zero to 500 million litres annually — a new business line built on conviction before commercial infrastructure existed to support it.$t$, $j$[{"text":"Established a new digital revenue channel and end-to-end operational model from the ground up.","strong":false},{"text":"Zero to 500 million litres annually","strong":true},{"text":"— a new business line built on conviction before commercial infrastructure existed to support it.","strong":false}]$j$::jsonb, 7, 'impact', true)
