insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000003', $t$decisions$t$, $t$Strategic Decisions$t$, $j${"eyebrow":"Executive Judgment in Practice","heading":"Strategic Decisions","items":[{"number":"01","title":"Stabilise or Accelerate — I Chose Both, Simultaneously","description":"The conventional call was to stabilise first. I rejected it. Rebuilt operations and drove commercial growth simultaneously — USD 36M revenue uplift and 30% OPEX reduction in the same 24-month window."},{"number":"02","title":"Rebuilding Governance Under Full Operating Load","description":"Eliminating 58% of stock loss required redesigning inventory governance while processing 20 million litres a month. Every change had to land without interrupting throughput — that constraint sharpens execution."},{"number":"03","title":"Launching a Revenue Channel Before the Data Justified It","description":"The B2B Fleet Card Programme didn't exist. No framework, no customer base, no structure to inherit. I built it end-to-end before the data existed to justify it. Within 6 months: 30% network sales increase. Conviction separates a decision from a delay."},{"number":"04","title":"I Decide. I Own. I Deliver.","description":"Every decision in this portfolio was made without escalation. I call it, I make it, I own it — regardless of outcome. Waiting for permission at this scale is not caution. It is failure."},{"number":"05","title":"Commissioning a 2 Million-Litre Depot — Full Operational Readiness From Zero","description":"Led end-to-end commissioning of a 2 million-litre city distribution depot — team build-out, capability design, and full operationalisation through to throughput stabilisation. Delivered operational readiness without inheriting structure or precedent."}]}$j$::jsonb, 3)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000004', $t$approach$t$, $t$How I Operate$t$, $j${"eyebrow":"How Decisions Get Made","heading":"How I Operate","quote":"\"14+ years at this scale has produced one consistent finding: the quality of the decision in the hard moment is the only thing that determines everything else.\"","principles":[{"number":"01","title":"Execution clarity over reporting complexity","description":"A clean decision made fast beats a perfect analysis made late. At 90 locations and USD 200M in revenue, analysis paralysis shows up in variance, throughput, and market share."},{"number":"02","title":"I own the outcome — before it happens, not after","description":"I make decisions early and own the outcome completely. Distributing accountability after the fact is how organisations lose clarity on who is responsible."},{"number":"03","title":"Revenue and cost are the same conversation","description":"Most operators sequence them. I run them simultaneously. The 30% OPEX reduction and USD 36M revenue growth happened in the same window. Separating the mandates creates the inefficiency you are trying to fix."},{"number":"04","title":"Systems must hold at scale","description":"Scale reveals design. A system that works at one location must perform identically at 90. I build governance, accountability, and performance frameworks that don't require my presence to function."},{"number":"05","title":"Proximity is a management tool, not a preference","description":"Data governs. Proximity reveals. I stay close enough to know when the numbers are lying — before reporting lag makes the problem expensive."},{"number":"06","title":"No escalation. Full accountability.","description":"At USD 200M scale, deferred decisions cost market share and margin. I act early, absorb the consequences, and deliver. No committee required."},{"number":"07","title":"Data tools accelerate the decision — they do not make it","description":"Where AI and data tools sharpen execution, I use them. Where they create noise or dependency, I don't. The judgment is mine. The tools serve it."}]}$j$::jsonb, 4)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000005', $t$capabilities$t$, $t$Core Capabilities$t$, $j${"eyebrow":"Functional Depth Across Three Disciplines","heading":"Core Capabilities","intro":["14+ years of operating at this scale — across Sub-Saharan Africa, India, and the GCC — has produced functional depth in three disciplines that rarely sit in one role simultaneously.","Operations ownership at USD 200M. Commercial strategy across 90 stations. End-to-end digital transformation. Each delivered concurrently, not sequentially."],"groups":[{"icon":"⚙️","title":"Operations & P&L","items":["P&L Ownership & OPEX/CAPEX (to USD 200M)","Multi-Site Network Leadership (90+ locations)","Supply Chain Governance & Inventory Optimisation","Greenfield Location Commissioning & Build-Out","KPI Scorecard Design & Performance Management","Regulatory & Risk Compliance","Vendor Negotiation & Strategic Procurement","Change Management & Organisational Redesign"]},{"icon":"📈","title":"Commercial & Growth","items":["Go-to-Market Strategy & Revenue Growth","Channel Development & Commercial Expansion","Multi-Site Network & Partner Management","B2B Fleet Programme Design & Rollout","Incentive Framework Design","Competitor Positioning & Market Strategy","Commercial Budget Ownership","Stakeholder & Board-Level Reporting"]},{"icon":"🖥️","title":"Transformation & Digital","items":["ERP Deployment (SAP, Odoo) — 90-location scale","CRM Implementation (Odoo, Zoho)","Retail Automation & System Integration","Business Requirements Authoring (BRD)","Process Automation & Digitisation","Power BI & Analytics Dashboard Design","Cross-Functional Leadership (1,200+ people)","Organisational Design & Capability Building","AI-Assisted Demand Forecasting & Decision Support"]}]}$j$::jsonb, 5)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000006', $t$projects$t$, $t$Key Projects$t$, $j${"eyebrow":"Enterprise-Scale Execution","heading":"Key Projects","items":[{"label":"Project 01","title":"Forecourt Automation & Real-Time KPI Dashboard","org":"Mount Meru Petroleum · 2023–2026","description":"Authored all BRDs and directed implementation of Forecourt Automation, Auto-Indenting, and Audit Management Systems across 90 stations. Designed the KPI scorecard that shifted network management from reactive to real-time — across commercial, financial, and operational targets simultaneously.","result":"40% operational efficiency gain post-deployment — measured against pre-deployment baselines"},{"label":"Project 02","title":"Fleet Management Card Programme — Built From Zero","org":"Mount Meru Petroleum · 2023–2025","description":"Owned full end-to-end go-to-market with no inherited structure and no existing customer base. Designed the framework, built the portal, integrated the station network, trained the network, and directed rollout — before commercial data existed to justify the investment.","result":"30% network sales increase within 6 months"},{"label":"Project 03","title":"Enterprise ERP / CRM / Digital Transformation","org":"Multi-Site Operations · 2023–2026","description":"Directed end-to-end digital transformation across 90 stations — all BRDs authored, all KPI frameworks owned, full organisational adoption managed across Ops, Sales, Finance, and Compliance. Transformed a fragmented, report-lagged operation into a digitally governed network with real-time P&L visibility.","result":"40% efficiency gain · Real-time visibility across all 90 stations · 1,200+ on unified data"}]}$j$::jsonb, 6)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000007', $t$career$t$, $t$Experience$t$, $j${"eyebrow":"14+ Years · 4 Countries · 3 Industries","heading":"Experience"}$j$::jsonb, 7)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000008', $t$journey$t$, $t$Career Journey$t$, $j${"eyebrow":"Progression of Scale & Responsibility","heading":"Career Journey","paragraphs":["Career progression built through increasing scale, operational complexity, and full ownership of business performance.","Started with unit-level operations in QSR — building foundations in cost control, team capability, and execution discipline. Expanded into multi-site environments with responsibility for network performance, dealer management, and commercial delivery across distributed operations.","Progressed into large-scale multi-site retail and distribution networks — taking on full P&L accountability across multi-province operations and integrating commercial strategy, operational governance, and system-led execution.","Across 14+ years the scope evolved from managing individual units to building and scaling enterprise-level operating systems across 90 locations, USD 200M revenue, and 1,200+ people.","Each step increased responsibility. The underlying focus remained constant — driving revenue growth and cost discipline simultaneously, under full operating load."],"close":"From unit operations to USD 200M P&L ownership — scaling systems, not just roles."}$j$::jsonb, 8)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000009', $t$about$t$, $t$Operating Philosophy$t$, $j${"eyebrow":"Operating Philosophy","heading":"Revenue growth. Cost discipline. Simultaneously.","items":[{"tag":"DIV","cls":"lbl","text":"Operating Philosophy"},{"tag":"H2","cls":"h2","text":"Revenue growth. Cost discipline. Simultaneously."},{"tag":"P","cls":"","text":"I run multi-site retail and operations networks — commercial and operational, simultaneously. Full P&L accountability at USD 200M scale, across 14+ years in India, Saudi Arabia, Zambia, and Kenya. Both sides of the business. One owner."},{"tag":"P","cls":"","text":"The results — USD 36M revenue uplift, 30% OPEX reduction, 32 months of record market share — came from making decisions early and holding the consequences. Not every call was clean. Rebuilding inventory governance while the network processed 20 million litres a month required deciding what to break first and what to protect."},{"tag":"P","cls":"","text":"My career spans petroleum retail at scale (Mount Meru Petroleum, Zambia), state-wide downstream oil network development (Reliance BP Mobility, India), and multi-site general management across QSR in the GCC. Three industries. Four countries. One consistent outcome."},{"tag":"P","cls":"repeat-narrative","text":"These results are not market-specific. The same discipline — early decisions, full accountability, simultaneous commercial and operational delivery — has produced above-target outcomes across every environment I have operated in. The operating principles built across these networks apply directly across any multi-site, high-volume, margin-sensitive business. The conditions change. The outcome does not. Delivered consistently across multiple markets and operating environments — not dependent on a single context."},{"tag":"P","cls":"control-narrative","text":"The standard I hold is simple: governance, accountability, and performance frameworks that function identically whether I am in the room or not — across 1 location or 90. I build operating systems that allow these outcomes to be repeated — not one-time results dependent on circumstance."},{"tag":"P","cls":"","text":"\"The numbers report what happened. I stay close enough to know what they are hiding.\""},{"tag":"SPAN","cls":"tag","text":"Retail Networks"},{"tag":"SPAN","cls":"tag","text":"P&L Ownership"},{"tag":"SPAN","cls":"tag","text":"Network Ops"},{"tag":"SPAN","cls":"tag","text":"Revenue Growth"},{"tag":"SPAN","cls":"tag","text":"OPEX Reduction"},{"tag":"SPAN","cls":"tag","text":"Digital Transformation"},{"tag":"SPAN","cls":"tag","text":"Sub-Saharan Africa"},{"tag":"SPAN","cls":"tag","text":"GCC · UAE"},{"tag":"SPAN","cls":"tag","text":"ERP · SAP · Odoo"},{"tag":"DIV","cls":"about-img-label","text":"Lake Oil Kenya · Nairobi, Kenya"},{"tag":"H4","cls":"","text":"Previous Mandate — Mount Meru Petroleum"},{"tag":"LI","cls":"","text":"USD 200M revenue · Full P&L & CAPEX ownership"},{"tag":"LI","cls":"","text":"90 retail stations across multiple provinces"},{"tag":"LI","cls":"","text":"20 million litres/month throughput"},{"tag":"LI","cls":"","text":"1,200+ people across Ops, Sales, Finance, HR, Compliance"},{"tag":"LI","cls":"","text":"Longest sustained market share record in company history"},{"tag":"H4","cls":"","text":"Target Roles & Markets"},{"tag":"LI","cls":"","text":"General Manager · Head of Sales"},{"tag":"LI","cls":"","text":"Head of Operations · Business Development"},{"tag":"LI","cls":"","text":"Sub-Saharan Africa · GCC · UAE · Global"},{"tag":"LI","cls":"","text":"Open to Relocation Globally"},{"tag":"H4","cls":"","text":"The Operating Model"},{"tag":"LI","cls":"","text":"Revenue growth and cost discipline — simultaneously"},{"tag":"LI","cls":"","text":"USD 36M growth + USD 3.6M+ savings in the same 24 months"},{"tag":"LI","cls":"","text":"30% OPEX reduction while sustaining 15% annual growth"},{"tag":"LI","cls":"","text":"Systems built to function without my presence at every station"}]}$j$::jsonb, 9)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000010', $t$conversion$t$, $t$Conversion$t$, $j${"lead":"Operating at scale is not a future step — it is the current baseline.","paragraphs":["I most recently ran a USD 200M multi-site business across 90 locations with full accountability across revenue, operations, and cost structure. The work is not functional — it is enterprise execution across commercial strategy, operational systems, and financial discipline.","The consistent outcome has been the ability to grow revenue while reducing cost without destabilising operations — delivered under full operating load, not in controlled environments."],"translates_label":"This translates directly into mandates where businesses need","translates_items":["Scale without loss of control","Growth without cost expansion","Systems that hold beyond individual leadership"],"mandate":"I am open to roles with full P&L accountability across multi-site or distributed operations — where the expectation is not to manage complexity, but to bring structure, discipline, and sustained performance to it.","close":"If the mandate requires both growth and control at scale — we should have a conversation."}$j$::jsonb, 10)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000011', $t$closing$t$, $t$Closing$t$, $j${"eyebrow":"Retail & Multi-Site Operations Executive","headline":"Built for Scale. Ready for the Next Mandate.","sub":"USD 200M P&L · 90 Stations · 14+ Years · 4 Countries"}$j$::jsonb, 11)
on conflict (section_key) do nothing;
insert into public.sections (id, section_key, title, body, sort_order)
values ('b0000000-0000-4000-8000-000000000012', $t$contact$t$, $t$Contact$t$, $j${"eyebrow":"Available for the Right Mandate","heading":"Let's talk about your next operation.","sub":"Targeting GM, Head of Sales, Head of Operations, and Business Development roles where the mandate is full P&L accountability, operational scale, and commercial delivery — simultaneously. Relevant for multi-site operations, retail networks, QSR, distribution, and high-volume consumer businesses.","availability":"Open to the right mandate","other":[{"tag":"P","cls":"","text":"Built to own the mandate from day one — P&L accountability, operational turnaround, and scalable growth. The track record speaks before the conversation starts."},{"tag":"P","cls":"contact-sub reveal","text":"Targeting GM, Head of Sales, Head of Operations, and Business Development roles where the mandate is full P&L accountability, operational scale, and commercial delivery — simultaneously. Relevant for multi-site operations, retail networks, QSR, distribution, and high-volume consumer businesses."},{"tag":"H3","cls":"","text":"Open to the Right Opportunity"},{"tag":"P","cls":"","text":"Targeting roles with full P&L accountability and operational scale across Sub-Saharan Africa, UAE, GCC, and global markets where both sides of the business must be owned and delivered at once."}]}$j$::jsonb, 12)
on conflict (section_key) do nothing;
